CREATE TABLE "__EFMigrationsHistory" (
    "MigrationId" TEXT NOT NULL CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY,
    "ProductVersion" TEXT NOT NULL
);

CREATE TABLE "ProtocolInbox" (
    "MessageId" TEXT NOT NULL CONSTRAINT "PK_ProtocolInbox" PRIMARY KEY,
    "ContentHash" TEXT NOT NULL,
    "FirstResponseJson" TEXT NOT NULL,
    "ReceivedAt" TEXT NOT NULL
);

CREATE TABLE "StopClosures" (
    "DemandId" TEXT NOT NULL CONSTRAINT "PK_StopClosures" PRIMARY KEY,
    "CommittedAt" TEXT NOT NULL
);

CREATE TABLE "UnloadBatches" (
    "UnloadBatchId" TEXT NOT NULL CONSTRAINT "PK_UnloadBatches" PRIMARY KEY,
    "DemandId" TEXT NOT NULL,
    "EvidenceJson" TEXT NOT NULL,
    "CompletedAt" TEXT NOT NULL
);

CREATE TABLE "VehicleRecoveryGenerations" (
    "AgvId" TEXT NOT NULL CONSTRAINT "PK_VehicleRecoveryGenerations" PRIMARY KEY,
    "ForcedRecoveryGeneration" INTEGER NOT NULL,
    "UpdatedAt" TEXT NOT NULL
);

CREATE TABLE "VehicleDispatchLeases" (
    "DemandId" TEXT NOT NULL CONSTRAINT "PK_VehicleDispatchLeases" PRIMARY KEY,
    "VehicleKey" TEXT NOT NULL,
    "AcquiredAt" TEXT NOT NULL,
    "ReleasedAt" TEXT NULL
);

CREATE TABLE "StationTaskTypeAdmissions" (
    "StationId" TEXT NOT NULL,
    "TaskType" TEXT NOT NULL,
    "PolicyVersion" INTEGER NOT NULL,
    CONSTRAINT "PK_StationTaskTypeAdmissions" PRIMARY KEY ("StationId", "TaskType")
);

CREATE TABLE "MissingPackages" (
    "Package" TEXT NOT NULL CONSTRAINT "PK_MissingPackages" PRIMARY KEY,
    "FirstSeenAt" TEXT NOT NULL,
    "LastSeenAt" TEXT NOT NULL,
    "Status" TEXT NOT NULL
);

